import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        HashMap<Integer, Integer> counts = new HashMap<>(2 * n + 1);
        int answer = 0;
        for (int i = 0; i < n; i++) {
            st.nextToken();
            answer = Math.max(answer, counts.merge((int) st.nval, 1, Integer::sum));
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := nextInt()
	counts := make(map[int]int, n)
	answer := 0
	for i := 0; i < n; i++ {
		v := nextInt()
		counts[v]++
		answer = max(answer, counts[v])
	}
	fmt.Println(answer)
}
